@@ -0,0 +1,47 @@
+---
+// The Gramaire wordmark — treatment "02 · Split stem" from the handoff. The
+// name is a portmanteau (grammar + Markdown) whose single shared middle `m`
+// is the brand hinge: `Gra` inks in `--fg`, `ark` in `--accent`, and the `m`
+// is bisected left-half `--fg` / right-half `--accent` by a hard-stop text
+// gradient. One weight/size throughout (IBM Plex Sans 700, tight tracking).
+interface Props {
+  size?: string;
+  class?: string;
+}
+const { size = "1.25rem", class: klass } = Astro.props;
+---
+
+<span class:list={["gramaire-wordmark", klass]} style={`--wm-size: ${size}`}>
+  <span class="wm-gra">Gra</span><span class="wm-m">m</span><span class="wm-ark"
+    >ark</span
+  >
+</span>
+
+<style>
+  .gramaire-wordmark {
+    font-family: var(--font-ui, "IBM Plex Sans", sans-serif);
+    font-weight: 700;
+    font-size: var(--wm-size);
+    letter-spacing: -0.04em;
+    line-height: 1;
+    white-space: nowrap;
+    display: inline-flex;
+  }
+  .wm-gra {
+    color: var(--gramaire-fg, var(--fg, #16181d));
+  }
+  .wm-ark {
+    color: var(--accent, #0a8f63);
+  }
+  .wm-m {
+    background: linear-gradient(
+      90deg,
+      var(--gramaire-fg, var(--fg, #16181d)) 0 50%,
+      var(--accent, #0a8f63) 50% 100%
+    );
+    -webkit-background-clip: text;
+    background-clip: text;
+    color: transparent;
+    -webkit-text-fill-color: transparent;
+  }
+</style>

@@ -0,0 +1,25 @@
+---
+// Starlight `SiteTitle` slot override — Starlight's built-in `logo`/`title`
+// options can't render the split-stem wordmark (they take a static image or
+// plain text), so we override the slot with the brand lockup: the railroad
+// logomark + the two-color wordmark, linked home. Base-prefixed so it resolves
+// under `/gramaire/` in CI.
+import GramaireMark from "./GramaireMark.astro";
+import GramaireWordmark from "./GramaireWordmark.astro";
+
+const href = import.meta.env.BASE_URL;
+---
+
+<a href={href} class="site-title gramaire-lockup">
+  <GramaireMark size={26} />
+  <GramaireWordmark size="1.25rem" />
+</a>
+
+<style>
+  .gramaire-lockup {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.5rem;
+    text-decoration: none;
+  }
+</style>

