+/* Gramaire design tokens — the emerald system from the Claude Design handoff.
+   One confident accent (emerald), explicit light/dark, IBM Plex everywhere.
+   A deliberate sibling of the FlatBars system (same token names) — Gramaire
+   owns emerald + cool-green neutrals. These raw `--*` tokens are consumed
+   directly by the standalone Landing/Lab pages and the LiveGrammar island;
+   the `--sl-*` block below re-skins Starlight's docs chrome from the same
+   values so the whole site themes from one source. */
+@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap");
+
 :root {
-  --sl-color-accent: #15b879;
-  --sl-color-accent-high: #2dd597;
-  --sl-color-text-accent: #15b879;
-  --sl-color-bg-nav: #ffffff;
-  --sl-color-black: #16181d;
-  --sl-color-gray-1: #f5f6f3;
-  --sl-color-gray-2: #e5e7eb;
+  --font-ui:
+    "IBM Plex Sans", ui-sans-serif, system-ui, -apple-system,
+    BlinkMacSystemFont, "Segoe UI", sans-serif;
+  --font-mono:
+    "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
+
+  /* Surfaces & ink — light */
+  --bg: #ffffff;
+  --bg-1: #f5faf7;
+  --bg-2: #edf5f0;
+  --bg-3: #e0efe7;
+  --fg: #16181d;
+  --fg-secondary: #1f3a31;
+  --fg-muted: #566860;
+  --fg-faint: #7d8d85;
+  --border: #dde9e3;
+  --border-strong: #c6dbd0;
+
+  /* Accent — #15b879 is demoted to the logomark node only; the UI/text
+     accent is the AA-contrast #0a8f63 (light) / #34d399 (dark). */
+  --accent: #0a8f63;
+  --accent-2: #066b4a;
+  --node: #15b879;
+  --accent-soft: color-mix(in srgb, var(--accent) 16%, var(--bg));
+  --accent-softer: color-mix(in srgb, var(--accent) 8%, var(--bg));
+
+  /* Terminal / status strip */
+  --out-bg: #0c130f;
+  --out-fg: #e8f1ec;
+
+  /* Syntax palette — meaning-mapped grammar highlighting */
+  --t-nonterm: var(--accent);
+  --t-term: #b4530a;
+  --t-action: #6f42c1;
+  --t-op: #7d8d85;
+  --t-comment: #7d8d85;
+
+  --radius: 6px;
+  --radius-lg: 10px;
+  --shadow-card:
+    0 1px 2px rgba(22, 24, 29, 0.04), 0 8px 26px -16px rgba(10, 143, 99, 0.28);
+  --shadow-pop:
+    0 16px 40px -12px rgba(22, 24, 29, 0.18), 0 0 0 1px rgba(22, 24, 29, 0.05);
+
+  /* Theme-aware brand ink: what the componentized logomark/wordmark bind
+     `currentColor`/`--gramaire-fg` to, so one inline SVG serves both themes. */
+  --gramaire-fg: var(--fg);
+
+  /* --- Starlight chrome, re-skinned from the tokens above --- */
+  --sl-font: var(--font-ui);
+  --sl-font-mono: var(--font-mono);
+  --sl-color-accent-low: var(--accent-softer);
+  --sl-color-accent: var(--accent);
+  --sl-color-accent-high: var(--accent-2);
+  --sl-color-text-accent: var(--accent);
+  --sl-color-white: var(--fg);
+  --sl-color-gray-1: var(--fg-secondary);
+  --sl-color-gray-2: var(--fg-muted);
+  --sl-color-gray-3: var(--fg-faint);
+  --sl-color-gray-4: var(--border-strong);
+  --sl-color-gray-5: var(--border);
+  --sl-color-gray-6: var(--bg-2);
+  --sl-color-gray-7: var(--bg-1);
+  --sl-color-black: var(--bg);
+  --sl-color-bg: var(--bg);
+  --sl-color-bg-nav: var(--bg);
+  --sl-color-bg-sidebar: var(--bg-1);
+  --sl-color-bg-inline-code: var(--bg-2);
+  --sl-color-hairline: var(--border);
+  --sl-color-hairline-light: var(--border);
+  --sl-color-hairline-shade: var(--border-strong);
+  --sl-color-text: var(--fg-muted);
+  --sl-color-text-invert: var(--bg);
+}
+
+:root[data-theme="dark"] {
+  --bg: #0e1512;
+  --bg-1: #131c18;
+  --bg-2: #1a2620;
+  --bg-3: #24332b;
+  --fg: #eaf2ed;
+  --fg-secondary: #c2d4ca;
+  --fg-muted: #8ea298;
+  --fg-faint: #73877e;
+  --border: #25332c;
+  --border-strong: #38493f;
+  --accent: #34d399;
+  --accent-2: #6ee7b7;
+  --node: #15b879;
+  --out-bg: #080d0a;
+  --out-fg: #e8f1ec;
+  --t-term: #f0a868;
+  --t-action: #c4a8ec;
+  --t-op: #73877e;
+  --t-comment: #73877e;
+
+  /* Re-assert the Starlight mappings under the dark attribute so they beat
+     Starlight's own `:root[data-theme='dark']` palette (higher specificity
+     than the `:root` block above). Each still resolves to the flipped token. */
+  --sl-color-accent-low: var(--accent-softer);
+  --sl-color-accent: var(--accent);
+  --sl-color-accent-high: var(--accent-2);
+  --sl-color-text-accent: var(--accent);
+  --sl-color-white: var(--fg);
+  --sl-color-gray-1: var(--fg-secondary);
+  --sl-color-gray-2: var(--fg-muted);
+  --sl-color-gray-3: var(--fg-faint);
+  --sl-color-gray-4: var(--border-strong);
+  --sl-color-gray-5: var(--border);
+  --sl-color-gray-6: var(--bg-2);
+  --sl-color-gray-7: var(--bg-1);
+  --sl-color-black: var(--bg);
+  --sl-color-bg: var(--bg);
+  --sl-color-bg-nav: var(--bg);
+  --sl-color-bg-sidebar: var(--bg-1);
+  --sl-color-bg-inline-code: var(--bg-2);
+  --sl-color-hairline: var(--border);
+  --sl-color-hairline-light: var(--border);
+  --sl-color-hairline-shade: var(--border-strong);
+  --sl-color-text: var(--fg-muted);
 }

 body {
-  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+  font-family: var(--font-ui);
+}
+
+code,
+pre,
+kbd,
+samp {
+  font-family: var(--font-mono);
+}
+
+::selection {
+  background: color-mix(in srgb, var(--accent) 26%, transparent);
 }

 .site-title {
   font-weight: 700;
   letter-spacing: -0.02em;
 }
+
+/* Railroad diagrams embedded in docs (the tutorial's <figure> SVGs, and the
+   same shapes the LiveGrammar island draws live) read as brand cards. */
+.sl-markdown-content figure img,
+.sl-markdown-content figure svg {
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background: var(--bg-1);
+  padding: 0.5rem;
+}
